import React, { useState } from 'react';
import { GoogleMap, Marker } from "@react-google-maps/api";

const mapStyles = { height: '400px', width: '100%' };
const defaultCenter = { lat: 41.2995, lng: 69.2401 }; // Tashkent

const MapComponent = ({ locationCoords, onLocationSelect }) => {
  const [selectedLocation, setSelectedLocation] = useState(locationCoords || defaultCenter);

  const handleMapClick = (event) => {
    const lat = event.latLng.lat();
    const lng = event.latLng.lng();
    const coords = { lat, lng };
    setSelectedLocation(coords);
    onLocationSelect(coords);
  };

  return (
    <GoogleMap
      mapContainerStyle={mapStyles}
      zoom={13}
      center={locationCoords || selectedLocation}
      onClick={handleMapClick}
    >
      {selectedLocation && <Marker position={selectedLocation} />}
    </GoogleMap>
  );
};

export default MapComponent;
